package com.pandinila.broadband_management.controller;import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.repository.NetworkMetricRepository;import com.pandinila.broadband_management.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/network-metrics") public class NetworkMetricController {private final NetworkMetricRepository repo;private final CustomerService customers;private final MonitoringService monitoring;public NetworkMetricController(NetworkMetricRepository r,CustomerService c,MonitoringService m){repo=r;customers=c;monitoring=m;}@GetMapping public List<NetworkMetric> all(){return repo.findAll();}@GetMapping("/customer/{customerId}") public List<NetworkMetric> history(@PathVariable String customerId){return monitoring.history(customers.all().stream().filter(c->c.getCustomerId().equals(customerId)).findFirst().orElseThrow());}@PostMapping public ComplaintPrediction save(@RequestBody NetworkMetric m,@RequestParam Long customerId){m.setCustomer(customers.one(customerId));return monitoring.process(m);}}
